# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: every deletion is logged (trash moves, trash deletion, archive prunes,
# stale lock), failures are reported and retried, show and the email list them.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')

    # one service, a copy kept in ready/ (no archiver)
    $script:readyCfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
    "steps": [ { "name": "dump" } ] } } }
'@ | ConvertFrom-Json

    function Get-Ev {
        param([string]$Type)
        @(Get-BackupEvents -EventsPath $script:paths.EventsPath | Where-Object { $_.type -eq $Type })
    }

    function Lock-Dir {
        # a dir the test user cannot empty: its own entries cannot be removed
        param([string]$Dir)
        New-Item -ItemType Directory -Force -Path $Dir | Out-Null
        Set-Content -LiteralPath (Join-Path $Dir 'f.bin') -Value ('z' * 1000)
        & chmod 555 $Dir
    }
}

AfterAll {
    Get-ChildItem -LiteralPath $Work -Recurse -Directory -ErrorAction SilentlyContinue | ForEach-Object { & chmod 755 $_.FullName 2>$null }
    Remove-TestWork
}

Describe 'trash moves' {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'dm'
        $script:paths = $t.Paths; $script:root = $t.Root
    }

    It 'logs a leftover wip and stage dir moved to trash, with a [trash] line' {
        foreach ($d in 'wip/app', 'stage/app') {
            New-Item -ItemType Directory -Force -Path (Join-Path $root $d) | Out-Null
            Set-Content -LiteralPath (Join-Path $root "$d/old.bin") -Value 'x'
        }
        $rows = @(Get-RunLines $readyCfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        $moves = Get-Ev 'trash.move'
        @($moves | ForEach-Object { $_.reason }) -join ',' | Should -Be 'wip-leftover,stage-leftover'
        $moves[0].svc | Should -Be 'app'
        $moves[0].status | Should -Be 'ok'
        $moves[0].trashName | Should -Match '^app-[0-9a-f]{12}$'
        $lines = @($rows | Where-Object { $_.Step -eq '[trash]' })
        $lines.Count | Should -Be 2
        $lines[0].Event | Should -Be 'done'
        $lines[0].Status | Should -Be 'ok'
        $lines[0].Detail | Should -Be "wip leftover (interrupted run?) -> trash/$($moves[0].trashName)"
    }

    It 'logs the routine local-copy drop as an event only, no line' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", "publishToReady": false,
    "syncArchive": { "script": "fixtures/mock-service.ps1" }, "steps": [ { "name": "dump" } ] } } }
'@ | ConvertFrom-Json
        $rows = @(Get-RunLines $cfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        (Get-Ev 'trash.move').reason | Should -Be 'local-copy-dropped'
        @($rows | Where-Object { $_.Step -eq '[trash]' }).Count | Should -Be 0
    }

    It 'logs a replaced un-archived backup and a failed dump' {
        Invoke-BackupRun -Config $readyCfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue | Out-Null
        Invoke-BackupRun -Config $readyCfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue | Out-Null
        (Get-Ev 'trash.move').reason | Should -Be 'replaced-unarchived'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump" }, { "name": "boom" } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue | Out-Null
        (Get-Ev 'trash.move')[-1].reason | Should -Be 'failed-dump'
    }
}

Describe 'emptying the trash' {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'dd'
        $script:paths = $t.Paths; $script:root = $t.Root
    }

    It 'deletes at the next run start, logged after run.begin and tied back to the move' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'wip/app') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'wip/app/old.bin') -Value ('x' * 3000)
        Invoke-BackupRun -Config $readyCfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null   # moves it
        $move = (Get-Ev 'trash.move')[0]
        $rows = @(Get-RunLines $readyCfg $paths -Journal | ForEach-Object { Split-RunLine $_ })            # deletes it

        $evs = @(Get-BackupEvents -EventsPath $paths.EventsPath)
        $del = @($evs | Where-Object { $_.type -eq 'trash.delete' })
        $del.Count | Should -Be 1
        $del[0].trashName | Should -Be $move.trashName
        $del[0].svc | Should -Be 'app'
        $del[0].reason | Should -Be 'wip-leftover'
        $del[0].fromRun | Should -Be $move.runId
        $del[0].status | Should -Be 'ok'
        $del[0].bytes | Should -BeGreaterThan 3000
        $del[0].files | Should -Be 1
        $del[0].runId | Should -Not -Be $move.runId
        # after this run's run.begin, so the deletion belongs to it
        [array]::IndexOf($evs, $del[0]) | Should -BeGreaterThan ([array]::IndexOf($evs, @($evs | Where-Object { $_.type -eq 'run.begin' })[-1]))
        (Test-Path (Join-Path $root "trash/$($move.trashName)")) | Should -BeFalse

        $line = @($rows | Where-Object { $_.Step -eq '[delete]' })
        $line.Count | Should -Be 1
        $line[0].Service | Should -Be 'app'
        $line[0].Status | Should -Be 'ok'
        $line[0].Detail | Should -Match ('^\d+ KB, 1 files  wip-leftover, run ' + $move.runId.Substring($move.runId.Length - 4) + '$')
        $rows[-1].Detail | Should -Match '  freed \d+ KB \(1 item\)$'
    }

    It 'deletes an item with no record, under the run' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'trash/junk') | Out-Null
        $rows = @(Get-RunLines $readyCfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        $del = (Get-Ev 'trash.delete')[0]
        Test-HasProp $del 'svc' | Should -BeFalse
        $line = @($rows | Where-Object { $_.Step -eq '[delete]' })[0]
        $line.Service | Should -Be 'run'
        $line.Detail | Should -Match 'no record: junk$'
    }

    It 'keeps an item it cannot delete, logs the failure, and frees it on a later run' -Skip:($IsWindows) {
        Lock-Dir (Join-Path $root 'trash/stuck')
        $rows = @(Get-RunLines $readyCfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        $del = (Get-Ev 'trash.delete')[0]
        $del.status | Should -Be 'fail'
        $del.error | Should -Not -BeNullOrEmpty
        (Test-Path (Join-Path $root 'trash/stuck')) | Should -BeTrue
        $line = @($rows | Where-Object { $_.Step -eq '[delete]' })[0]
        $line.Status | Should -Be 'FAIL'
        $line.Detail | Should -Match '^! stuck: .*; kept, retried next run$'
        $rows[-1].Detail | Should -Match '1 trash item kept$'

        & chmod 755 (Join-Path $root 'trash/stuck')
        Invoke-BackupRun -Config $readyCfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue | Out-Null
        (Get-Ev 'trash.delete')[-1].status | Should -Be 'ok'
        (Test-Path (Join-Path $root 'trash/stuck')) | Should -BeFalse
    }

    It 'shows nothing when the trash is empty' {
        $rows = @(Get-RunLines $readyCfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        @($rows | Where-Object { $_.Step -eq '[delete]' }).Count | Should -Be 0
        $rows[-1].Detail | Should -Be '1 ok, 0 failed, 1 planned'
    }
}

Describe 'stale lock' {
    It 'records the dead pid on run.begin and warns' {
        $t = New-SpoolTestEnv -Prefix 'dl'
        $script:paths = $t.Paths
        Set-Content -LiteralPath $paths.LockPath -Value 999999   # no such process
        $rows = @(Get-RunLines $readyCfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        (Get-Ev 'run.begin')[0].staleLockPid | Should -Be '999999'
        $warn = @($rows | Where-Object { $_.Service -eq 'run' -and $_.Status -eq 'WARN' })[0]
        $warn.Detail | Should -Match '^stale lock removed: pid 999999 no longer running'
    }
}

Describe 'archive prunes' {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'dp'
        $script:paths = $t.Paths; $script:n = $t.N
        $script:dest = Join-Path $Work "prune-$n"
        $script:svcDir = Join-Path $dest 'app'
        $script:cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", "publishToReady": false,
    "syncArchive": { "script": "../src/recipes/archive-copy.ps1", "env": { "ARCHIVE_DEST": "__DEST__", "ARCHIVE_KEEP": "1" } },
    "steps": [ { "name": "dump" } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        # one prior archive in the log, with its dir
        $script:old = Join-Path $svcDir '20261101-000000'
        New-Item -ItemType Directory -Force -Path $svcDir | Out-Null
        Add-Content -LiteralPath $paths.EventsPath -Value (@{ ts = '2026-11-01T00:00:00Z'; type = 'service.archived'; svc = 'app'; path = $old } | ConvertTo-Json -Compress)
    }

    It 'measures what it prunes and says so' {
        New-Item -ItemType Directory -Force -Path $old | Out-Null
        Set-Content -LiteralPath (Join-Path $old 'a.bin') -Value ('a' * 5000)
        $rows = @(Get-RunLines $cfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        $p = (Get-Ev 'service.archive-pruned')[0]
        $p.path | Should -Be $old
        $p.bytes | Should -BeGreaterThan 5000
        $p.files | Should -Be 1
        (Test-Path $old) | Should -BeFalse
        @($rows | Where-Object { $_.Step -eq 'sync-archive' -and $_.Event -eq 'msg' })[0].Detail | Should -Match ('^pruned ' + [regex]::Escape($old) + ' \(\d+ KB, 1 files\)$')
        @($rows | Where-Object { $_.Service -eq 'app' -and $_.Step -eq '-' -and $_.Event -eq 'end' })[0].Detail | Should -Match 'pruned 1'
    }

    It 'does not record a failed prune as pruned: warns, stays ok, prunes it on a later run' -Skip:($IsWindows) {
        Lock-Dir $old
        $rows = @(Get-RunLines $cfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        @(Get-Ev 'service.archive-pruned' | Where-Object { $_.path -eq $old }).Count | Should -Be 0
        $f = (Get-Ev 'service.archive-prunefail')[0]
        $f.path | Should -Be $old
        $f.status | Should -Be 'fail'
        (Get-Ev 'service.end')[0].status | Should -Be 'ok'
        $warn = @($rows | Where-Object { $_.Step -eq 'sync-archive' -and $_.Status -eq 'WARN' })[0]
        $warn.Detail | Should -Match '^prune failed, kept for next run: '
        @(Get-Ev 'step.end' | Where-Object { $_.step -eq 'sync-archive' })[0].warnings[0] | Should -Match '^prune failed'
        @($rows | Where-Object { $_.Service -eq 'app' -and $_.Step -eq '-' -and $_.Event -eq 'end' })[0].Detail | Should -Match '1 prune failed'

        & chmod 755 $old
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue | Out-Null
        @(Get-Ev 'service.archive-pruned' | Where-Object { $_.path -eq $old }).Count | Should -Be 1
        (Test-Path $old) | Should -BeFalse
    }
}

Describe 'deletions in show and the email' {
    It 'lists deletions in a run-level block, moves under their service, totals in the email' -Skip:($IsWindows) {
        $t = New-SpoolTestEnv -Prefix 'ds'
        $script:paths = $t.Paths; $root = $t.Root
        # an earlier run's drop of another service, a stuck item, and a leftover for app
        Add-Content -LiteralPath $paths.EventsPath -Value (@{ ts = '2026-11-17T23:00:00Z'; type = 'trash.move'; runId = '20261117-230000-a558'; svc = 'forgejo'; reason = 'local-copy-dropped'; trashName = 'forgejo-0123456789ab'; status = 'ok' } | ConvertTo-Json -Compress)
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'trash/forgejo-0123456789ab') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'trash/forgejo-0123456789ab/d.bin') -Value ('d' * 4000)
        Lock-Dir (Join-Path $root 'trash/stuck')
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'wip/app') | Out-Null
        $runId = Invoke-BackupRun -Config $readyCfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue

        $events = @(Get-BackupEvents -EventsPath $paths.EventsPath)
        $run = (Get-RunStates -Events $events -LockPath $paths.LockPath)[-1]
        $detail = Get-RunDetail -Events $events -Run $run
        @($detail.Services | ForEach-Object { $_.Service }) -join ',' | Should -Be 'app'   # no row for forgejo
        $text = (Format-RunDetail -Detail $detail) -join "`n"
        $text | Should -Match '(?m)^      moved to trash: wip-leftover$'
        $text | Should -Match '(?m)^  deletions\s+freed \d+ KB in 1 item; 1 failed$'
        $text | Should -Match '(?m)^      delete  forgejo\s+\d+ KB\s+1 files  local-copy-dropped, run a558$'
        $text | Should -Match '(?m)^    ! delete  \(no record\)\s+kept: stuck: '

        $mail = Format-RunReport -EventsPath $paths.EventsPath -RunId $runId
        $mail | Should -Match '(?m)^  ! \(no record\)\s+trash item kept: stuck: '
        $mail | Should -Match '(?m)^  -- freed \d+ KB in 1 item; 1 failed$'
        & chmod 755 (Join-Path $root 'trash/stuck')
    }
}
